package com.lendup.reservas.contracts;
import static org.junit.jupiter.api.Assertions.*; import com.lendup.reservas.interfaces.rest.dto.RequestDtos.CrearSolicitud; import com.lendup.reservas.interfaces.rest.dto.ResponseDtos.ReservaResponse; import java.math.BigDecimal; import java.time.*; import java.util.UUID; import org.junit.jupiter.api.Test; import tools.jackson.databind.json.JsonMapper;
class FrontendContractTest { private final JsonMapper json=JsonMapper.builder().findAndAddModules().build();
  @Test void cuerpoCrearSolicitudConservaSnakeCaseYLocalDateTime()throws Exception{UUID id=UUID.randomUUID();CrearSolicitud dto=json.readValue("{\"publicacion_id\":\""+id+"\",\"desde\":\"2026-11-01T09:00:00\",\"hasta\":\"2026-11-02T09:00:00\"}",CrearSolicitud.class);assertEquals(id,dto.publicacion_id());assertEquals(LocalDateTime.of(2026,11,1,9,0),dto.desde());}
  @Test void reservaExponeCamposConsumidosPorMapper()throws Exception{ReservaResponse r=new ReservaResponse(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),LocalDateTime.now(),LocalDateTime.now().plusDays(1),"CONFIRMADA",BigDecimal.ONE,null,"PEN","Campus","u","e","d","c",Instant.now(),null,null,null,null,Instant.now());String body=json.writeValueAsString(r);for(String field:new String[]{"solicitud_id","agenda_id","tarifa_diaria_acordada","garantia_monetaria_acordada","moneda_acordada","lugar_intercambio_acordado","condiciones_uso_acordadas","condiciones_entrega_acordadas","condiciones_devolucion_acordadas","condiciones_cancelacion_acordadas","confirmada_en"})assertTrue(body.contains("\""+field+"\""),field);}
}
